"""Read-only progress of one frozen prospective57-original cohort."""
import json
from pathlib import Path
ROOT=Path('/home/zhuyulab/ns3-workspace/ros2_ws/ros2-multi-robot-automap')
def load(p):
    try:return json.loads(p.read_text())
    except (FileNotFoundError,json.JSONDecodeError):return None
a=load(Path('/tmp/p3b5_v67_commands.json'))
if a:
    print(json.dumps(dict(stage=a['stage'],status=a.get('dispatcher_status'),finished=a.get('finished_at_utc'),
        owners=[dict(name=e['plan']['name'],returncode=e.get('returncode'),live=Path('/proc',str(e['pid'])).exists()) for e in a['executions']]),ensure_ascii=False))
rows=[];infra=[];operational=[]
for base in ('log/p3b5','log/p2d_baseline'):
    for folder in sorted((ROOT/base).glob('p3b5_v67_*')):
        summary=load(folder/'summary.json')
        if summary:
            es=summary['episodes'];es=es.values() if isinstance(es,dict) else es
            infra.extend([e.get('episode_id',e.get('result_path')) for e in es if e.get('infrastructure_failure')])
            operational.extend([e.get('episode_id',e.get('result_path')) for e in es if e.get('operational_failure')])
        for path in folder.rglob('*.json'):
            r=load(path)
